import{accountAuthClient}from './owner-auth.js';
import{modal,closeModal,toast}from './ui.js';
import{cropRect,imageKind,AVATAR_BYTES}from './account-avatar-core.js';
import{createAvatarStore}from './account-avatar-store.js';
export const avatarCamera='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 6h4l2-3h4l2 3h4a2 2 0 0 1 2 2v11H2V8a2 2 0 0 1 2-2Z"/><circle cx="12" cy="12" r="4"/></svg>';
const person='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="12" cy="7" r="4"/><path d="M4 22v-4a8 8 0 0 1 16 0v4Z"/></svg>';
const store=createAvatarStore({getClient:accountAuthClient});let avatarUser=null;
export function syncAvatarSession(state){const uid=state.signedIn?state.userId:null;if(uid!==avatarUser){avatarUser=uid;store.clear();}}
const changed=uid=>window.dispatchEvent(new CustomEvent('salah:account-avatar',{detail:{userId:uid}}));
const showImage=(target,url)=>{target.innerHTML=url?'<img alt="" aria-hidden="true">':person;if(url){const img=target.querySelector('img');img.referrerPolicy='no-referrer';img.src=url;img.onerror=()=>{if(target.isConnected)target.innerHTML=person;};}};
export function mountMenuAvatar(host,state){if(!state.signedIn||!state.userId)return;const target=host.querySelector('[data-menu-avatar]');if(!target)return;void store.get(state.userId).then(url=>{if(target.isConnected)showImage(target,url);}).catch(()=>{});}
const message=e=>e?.message==='image_format'?'Выберите фото JPG, PNG или WebP.':e?.message==='image_size'?'Фото должно быть меньше 20 МБ.':e?.message==='export_size'?'Не удалось уменьшить фото. Выберите другое изображение.':e?.message==='image_dimensions'?'Изображение слишком большое. Выберите другое фото.':e?.message==='sign_in_required'?'Войдите в аккаунт и повторите.':'Не удалось сохранить фото. Проверьте соединение и повторите.';
export async function openAvatarCrop(file,{onSave,isActive=()=>true}={}){await imageKind(file);const original=URL.createObjectURL(file),image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('image_format'));image.src=original;});cropRect(image.naturalWidth,image.naturalHeight);if(!isActive()){URL.revokeObjectURL(original);return;}
 modal('<div class="avatar-crop-editor"><div class="modal-head"><h2>Фото профиля</h2><button class="text-button" data-close>Закрыть</button></div><div class="avatar-crop-view"><canvas id="avatar-crop-canvas" width="512" height="512" role="img" aria-label="Предпросмотр фото профиля"></canvas></div><p class="avatar-crop-hint">Двигайте фото, чтобы выбрать кадр</p><label class="avatar-zoom-label" for="avatar-zoom">Масштаб<input type="range" id="avatar-zoom" min="1" max="3" step=".05" value="1"></label><p id="avatar-crop-status" class="muted" role="status"></p><button type="button" class="button" id="avatar-save-photo">Сохранить фото</button></div>');
 const root=document.querySelector('.avatar-crop-editor'),canvas=root.querySelector('canvas'),zoom=root.querySelector('#avatar-zoom'),status=root.querySelector('#avatar-crop-status'),save=root.querySelector('#avatar-save-photo'),dialog=document.getElementById('modal');let x=.5,y=.5,drag=null,busy=false;
 const draw=()=>{const c=cropRect(image.naturalWidth,image.naturalHeight,Number(zoom.value),x,y),ctx=canvas.getContext('2d');ctx.clearRect(0,0,512,512);ctx.drawImage(image,c.sx,c.sy,c.sw,c.sh,0,0,512,512);};draw();zoom.oninput=draw;
 canvas.onpointerdown=e=>{if(busy||drag)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture?.(e.pointerId);};canvas.onpointermove=e=>{if(!drag||busy||e.pointerId!==drag.id)return;const c=cropRect(image.naturalWidth,image.naturalHeight,Number(zoom.value),x,y),w=canvas.getBoundingClientRect().width,dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(image.naturalWidth>c.sw)x=Math.max(0,Math.min(1,(c.sx-dx*c.sw/w)/(image.naturalWidth-c.sw)));if(image.naturalHeight>c.sh)y=Math.max(0,Math.min(1,(c.sy-dy*c.sh/w)/(image.naturalHeight-c.sh)));drag={id:e.pointerId,x:e.clientX,y:e.clientY};draw();};canvas.onpointerup=canvas.onpointercancel=e=>{if(drag?.id===e.pointerId)drag=null;};
 const checkActive=()=>{if(!isActive()&&root.isConnected)closeModal();};window.addEventListener('salah:counter-status',checkActive);window.addEventListener('hashchange',checkActive);dialog.addEventListener('close',()=>{URL.revokeObjectURL(original);window.removeEventListener('salah:counter-status',checkActive);window.removeEventListener('hashchange',checkActive);},{once:true});
 save.onclick=async()=>{if(busy||!isActive())return;busy=true;save.disabled=true;zoom.disabled=true;status.textContent='Сохраняем фото…';try{let blob;for(const quality of [.82,.65,.5]){blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=AVATAR_BYTES)break;}if(!blob||blob.size>AVATAR_BYTES)throw Error('export_size');await onSave(blob);if(root.isConnected)closeModal();}catch(e){if(root.isConnected){status.textContent=message(e);save.disabled=false;zoom.disabled=false;busy=false;}}};
 }catch(e){URL.revokeObjectURL(original);throw e;}}
export function mountAccountAvatar(container,{userId,isActive=()=>true,avatarStore=store}){const host=container.querySelector('#account-avatar-editor');if(!host)return;host.innerHTML='<button type="button" class="account-avatar-circle" id="account-avatar-photo" aria-label="Добавить или изменить фото профиля"><span class="account-avatar-image">'+person+'</span><span class="account-avatar-camera">'+avatarCamera+'</span></button><div class="account-avatar-controls"><strong>Фото профиля</strong><button type="button" class="text-button" id="account-avatar-choose">Добавить фото</button><button type="button" class="text-button" id="account-avatar-remove" hidden>Удалить фото</button><p id="account-avatar-status" class="muted" role="status"></p></div><input type="file" id="account-avatar-file" accept="image/jpeg,image/png,image/webp" hidden>';
 const target=host.querySelector('.account-avatar-image'),input=host.querySelector('input'),choose=host.querySelector('#account-avatar-choose'),remove=host.querySelector('#account-avatar-remove'),status=host.querySelector('#account-avatar-status');
 const refresh=()=>avatarStore.get(userId).then(url=>{if(!isActive()||!host.isConnected)return;showImage(target,url);choose.textContent=url?'Сменить фото':'Добавить фото';remove.hidden=!url;}).catch(()=>{});void refresh();
 const checkAccount=()=>{if(!host.isConnected){window.removeEventListener('salah:counter-status',checkAccount);return;}if(!isActive()){showImage(target,null);choose.disabled=true;remove.hidden=true;host.querySelector('#account-avatar-photo').disabled=true;}};window.addEventListener('salah:counter-status',checkAccount);const pick=()=>{if(isActive())input.click();};host.querySelector('#account-avatar-photo').onclick=pick;choose.onclick=pick;
 input.onchange=async()=>{const file=input.files?.[0];input.value='';if(!file||!isActive())return;status.textContent='Открываем фото…';try{await openAvatarCrop(file,{isActive,onSave:async blob=>{await avatarStore.save(userId,blob);changed(userId);if(isActive()){status.textContent='Фото сохранено';await refresh();}toast('Фото сохранено');}});if(isActive())status.textContent='';}catch(e){if(isActive())status.textContent=message(e);}};
 remove.onclick=()=>{if(!isActive())return;modal('<div class="modal-head"><h2>Удалить фото?</h2><button class="text-button" data-close>Отмена</button></div><p>Из аккаунта будет удалено только фото профиля.</p><button class="button" id="avatar-confirm-remove">Удалить фото</button><p class="muted" id="avatar-remove-status" role="status"></p>');const button=document.getElementById('avatar-confirm-remove'),line=document.getElementById('avatar-remove-status');button.onclick=async()=>{button.disabled=true;try{await avatarStore.remove(userId);changed(userId);if(button.isConnected)closeModal();if(isActive()){status.textContent='Фото удалено';void refresh();}}catch(e){if(button.isConnected){line.textContent=message(e);button.disabled=false;}}};};
}
